package com.bananalab.lite;
import java.util.*;import org.json.*;
public class Stage36Check{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception{String root=args[0];Semilla m=SemillaCheck.load(root+"/assets/language");CreatorSession c=new CreatorSession();
  CreatorSession.Result first=c.apply(m,"crea a Tony una banana detective con sobretodo; agrega un gato llamado Milo; Tony habla con Milo mientras entra el tomate",null);check(first.commit!=null,"multi task "+first.text);SceneDraft base=first.commit;check(base.cast.size()==3&&base.actions.size()==3,"three actors and talk+entry");String before=base.json().toString(),tony=base.get("banana").designId;
  CreatorSession.Result edited=c.apply(m,"deja todo igual pero cambia al que entro por un conejo y hacelo mas alto",base);check(edited.commit!=null,"swap and height "+edited.text);SceneDraft d=edited.commit;check(d.get("tomate").kind.equals("conejo")&&d.get("tomate").look.contains("alto"),"grounded swap and focus");check(d.actions.equals(base.actions)&&d.get("banana").designId.equals(tony),"preserve unaffected design and timeline");check(!d.get("tomate").designId.equals(base.get("tomate").designId),"explicit replacement new design");check(c.apply(m,"que hiciste",d).text.contains("2 pasos"),"execution receipt");
  String receipt=c.lastTask;CreatorSession.Result bad=c.apply(m,"pone el fondo en la playa; destrui el universo",base);check(bad.commit==null&&base.json().toString().equals(before)&&receipt.equals(c.lastTask),"atomic failure no partial commit");
  bad=c.apply(m,"pone el fondo en la playa y explota la luna; hacelo mas alto",base);check(bad.commit==null&&base.json().toString().equals(before),"unparsed edit conjunction rejected");
  bad=c.apply(m,"cambia al que entro por un dragon y hacelo mas alto",base);check(bad.commit==null,"unsupported replacement rejected");
  CreatorSession draft=new CreatorSession();CreatorSession.Result prepared=draft.apply(m,"cambia al que entro por un conejo; hacelo mas alto sin dibujar",base);check(prepared.commit==null&&draft.pending!=null&&draft.pending.get("tomate").kind.equals("conejo"),"compound draft isolation "+prepared.text);check(draft.undo.size()==1,"one atomic draft undo");draft.apply(m,"deshacer",base);check(draft.pending==null,"one-step draft rollback");
  check(SceneGuide.reply("como es Tony",d).contains("sobretodo"),"grounded design query");check(SceneGuide.reply("con quien habla Tony",d).contains("milo"),"grounded relationship query");check(SceneGuide.reply("que hace el que entro",d).contains("entra"),"grounded action query");
  for(SceneDraft.Actor a:base.cast)for(SceneDraft.Actor b:base.cast)if(a!=b)check(Math.abs(a.x-b.x)>=22,"entrance destination does not overlap cast");
  CreatorPersistenceCheck.Fake f=new CreatorPersistenceCheck.Fake();ProjectMemory.reply(f,"recorda que Tony vive en el bosque");ProjectMemory.reply(f,"recorda que Milo es detective");check(ProjectMemory.reply(f,"mis recuerdos").contains("[1]"),"memory IDs");ProjectMemory.reply(f,"corregí el recuerdo 1: Tony vive en la playa");check(ProjectMemory.reply(f,"que te dije sobre Tony").contains("playa")&&!ProjectMemory.related(f,"Tony").contains("bosque"),"corrected fact retrieval");ProjectMemory.reply(f,"olvida el recuerdo 1");String rows=ProjectMemory.reply(f,"mis recuerdos");check(!rows.contains("Tony")&&rows.contains("Milo")&&rows.contains("[2]"),"delete one and stable IDs");ProjectMemory.reply(f,"recorda que la serie es de misterio");check(ProjectMemory.reply(f,"mis recuerdos").contains("[3]"),"IDs never reused");
  String saved=f.getSharedPreferences("banana-project-memory",0).getString("facts","");f.fail=true;boolean fail=false;try{ProjectMemory.reply(f,"corregi el recuerdo 2: Milo es cocinero");}catch(Exception e){fail=true;}check(fail&&saved.equals(f.getSharedPreferences("banana-project-memory",0).getString("facts","")),"memory storage failure preserves state");
  CreatorMemory.save(f,c,d);CreatorSession loaded=CreatorMemory.load(f);check(loaded.lastTask.equals(receipt),"receipt persists");BananaEngine.Result summary=BananaEngine.run(f,"resumi mi proyecto",new ArrayList<String[]>(),"",true,m);check(summary.text.contains("conejo")&&summary.text.contains("misterio"),"unified persisted scene and memory summary");
  System.out.println("PASS compound tasks, targeted replacement/traits, atomic failure, draft undo, grounded queries, stable memory CRUD, persistence and combined project summary");
 }
}
